CREATE POLICY "Admins upload website media" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'website-media' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins view website media" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'website-media' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins update website media" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'website-media' AND public.has_role(auth.uid(), 'admin')) WITH CHECK (bucket_id = 'website-media' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins delete website media" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'website-media' AND public.has_role(auth.uid(), 'admin'));